async function loadExcelMaster(){
  try{
    if(typeof XLSX==='undefined')throw new Error('Bibliothèque Excel indisponible');
    const response=await fetch('recettes.xlsx?v=4.0',{cache:'no-store'});if(!response.ok)throw new Error('recettes.xlsx introuvable');
    const workbook=XLSX.read(await response.arrayBuffer(),{type:'array'}),cell=(ws,a)=>ws[a]?.v??'';
    const reserved=new Set(['Semaines_Types','REC_Template']),recipes=[];
    for(const sheetName of workbook.SheetNames){if(reserved.has(sheetName))continue;const ws=workbook.Sheets[sheetName];
      const name=String(cell(ws,'B3')).trim(),category=String(cell(ws,'B4')).trim(),time=+cell(ws,'B5'),seasons=String(cell(ws,'B6')).split(',').map(v=>v.trim()).filter(Boolean);if(!name)continue;
      let ih=0,sh=0;for(let r=1;r<=220;r++){const v=String(cell(ws,'A'+r)).trim().toUpperCase();if(v==='INGRÉDIENTS PAR PERSONNE')ih=r;if(v==='ÉTAPES DE PRÉPARATION'){sh=r;break}}
      const ingredients=[];for(let r=ih+2;r<sh;r++){const n=String(cell(ws,'A'+r)).trim(),q=+cell(ws,'B'+r),u=String(cell(ws,'C'+r)).trim(),g=String(cell(ws,'D'+r)).trim(),role=String(cell(ws,'E'+r)||'Complément').trim(),ss=String(cell(ws,'F'+r)||'Toutes').split(',').map(x=>x.trim()).filter(Boolean);if(n&&q>0&&u&&g)ingredients.push([n,q,u,g,role,ss])}
      const steps=[];for(let r=sh+2;r<=sh+100;r++){const order=+cell(ws,'A'+r),value=String(cell(ws,'B'+r)).trim();if(order>0&&value)steps.push({order,value})}steps.sort((a,b)=>a.order-b.order);
      if(ingredients.length&&steps.length)recipes.push({n:name,c:category,t:time,s:seasons,i:ingredients,steps:steps.map(x=>x.value)});
    }
    const ws=workbook.Sheets['Semaines_Types'];if(!ws)throw new Error('Semaines_Types absent');
    const rows=XLSX.utils.sheet_to_json(ws,{range:2,defval:''}),templates={},fruitTemplates={};
    for(const x of rows){const key=String(x.Saison).trim()+' '+String(x.Semaine).trim();if(x.Type==='Repas'){const di=DAYS.indexOf(String(x.Jour).trim()),i=di*2+(String(x.Repas).trim()==='Soir'?1:0);(templates[key]??=Array(14).fill('RepasLibre'))[i]=String(x.Recette).trim()||'RepasLibre'}else if(x.Type==='Fruit'){(fruitTemplates[key]??=[]).push({n:String(x.Fruit).trim(),q:+x['Quantité pour 2'],u:String(x.Unité).trim()||'unité',order:+x.Position})}}
    for(const v of Object.values(fruitTemplates))v.sort((a,b)=>a.order-b.order).forEach(x=>delete x.order);
    const fruits=[
      ['Pomme',['Spring','Autumn','Winter'],'unité',3],['Poire',['Summer','Autumn','Winter'],'unité',3],['Banane',['Spring','Summer','Autumn','Winter'],'unité',3],['Kiwi',['Spring','Autumn','Winter'],'unité',3],['Orange',['Spring','Autumn','Winter'],'unité',3],['Clémentine',['Autumn','Winter'],'unité',3],['Mandarine',['Autumn','Winter'],'unité',3],['Pamplemousse',['Spring','Autumn','Winter'],'unité',2],['Pêche',['Summer'],'unité',3],['Nectarine',['Summer'],'unité',3],['Abricot',['Summer'],'unité',4],['Prune',['Summer','Autumn'],'unité',3],['Raisin',['Autumn'],'g',300],['Fraise',['Spring','Summer'],'g',250],['Cerise',['Spring','Summer'],'g',250],['Melon',['Summer'],'unité',1],['Pastèque',['Summer'],'unité',1],['Framboise',['Summer'],'g',250],['Myrtille',['Summer'],'g',250],['Mûre',['Summer','Autumn'],'g',250],['Figue',['Summer','Autumn'],'unité',3],['Ananas',['Spring','Summer','Autumn','Winter'],'unité',1],['Mangue',['Spring','Summer','Autumn','Winter'],'unité',2],['Litchi',['Winter'],'g',300]
    ].map(x=>({n:x[0],s:x[1],u:x[2],q:x[3]}));
    const fruitPrices={'Pomme':[.48,'unité'],'Poire':[.62,'unité'],'Banane':[.42,'unité'],'Kiwi':[.55,'unité'],'Orange':[.62,'unité'],'Clémentine':[.28,'unité'],'Mandarine':[.32,'unité'],'Pamplemousse':[1.15,'unité'],'Pêche':[.68,'unité'],'Nectarine':[.70,'unité'],'Abricot':[.35,'unité'],'Prune':[.30,'unité'],'Raisin':[4.5,'kg'],'Fraise':[11.32,'kg'],'Cerise':[9,'kg'],'Melon':[2.61,'unité'],'Pastèque':[4.5,'unité'],'Framboise':[25.51,'kg'],'Myrtille':[16,'kg'],'Mûre':[18,'kg'],'Figue':[.65,'unité'],'Ananas':[2.61,'unité'],'Mangue':[1.8,'unité'],'Litchi':[8,'kg']};
    BASE.recipes=recipes;BASE.templates=templates;BASE.fruits=fruits;BASE.fruitPrices=fruitPrices;BASE.prices={...BASE.prices,...fruitPrices};BASE.fruitTemplates=fruitTemplates;BASE.fruitOptions={};BASE.catalogVersion=String(cell(ws,'B1')||'4.0.0');
  }catch(e){console.warn('Catalogue Excel non chargé, utilisation du catalogue intégré',e)}
}
const normalizeV28=normalizeState;
normalizeState=function(input){
  const state=normalizeV28(input);
  state.fruits=Array.isArray(state.fruits)?state.fruits:structuredClone(BASE.fruits||[]);
  state.fruitTemplates=(state.fruitTemplates&&typeof state.fruitTemplates==='object'&&!Array.isArray(state.fruitTemplates))?state.fruitTemplates:structuredClone(BASE.fruitTemplates||{});
  state.fruitOptions=(state.fruitOptions&&typeof state.fruitOptions==='object'&&!Array.isArray(state.fruitOptions))?state.fruitOptions:structuredClone(BASE.fruitOptions||{});
  state.catalogVersion=String(state.catalogVersion||'');
  for(const week of Object.values(state.weeks||{})) week.fruitOverrides=(week.fruitOverrides&&typeof week.fruitOverrides==='object')?week.fruitOverrides:{};
  return state;
};

