UI.setFruitV4=function(i,n){const f=App.state.fruits.find(x=>x.n===decodeURIComponent(n));if(!f)return;App.week().fruitOverrides[i]={n:f.n,q:f.q,u:f.u};Store.save();this.close();this.renderPlanning();this.renderCourses()};
UI.setTemplateFruitV4=function(i,n){const f=App.state.fruits.find(x=>x.n===decodeURIComponent(n));if(!f)return;App.state.fruitTemplates[templateSelect.value][i]={n:f.n,q:f.q,u:f.u};Store.save();this.close();this.renderTemplates()};
(async()=>{await loadExcelMaster();App.init().catch(e=>{console.error('Initialisation impossible',e);Store.status('⚠ Erreur de démarrage','error')})})();
